PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "permissions" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "guard_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "model_has_permissions" ("permission_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, primary key ("permission_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "model_has_roles" ("role_id" integer not null, "model_type" varchar not null, "model_id" integer not null, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("role_id", "model_id", "model_type"));
CREATE TABLE IF NOT EXISTS "role_has_permissions" ("permission_id" integer not null, "role_id" integer not null, foreign key("permission_id") references "permissions"("id") on delete cascade, foreign key("role_id") references "roles"("id") on delete cascade, primary key ("permission_id", "role_id"));
CREATE TABLE IF NOT EXISTS "cases" ("id" varchar not null, "name" varchar not null, "ai_columns" text not null default '[]', "eden_api_key" varchar, "eden_region" varchar not null default 'us', "model_allowlist" text not null default '[]', "col_order" text not null default '[]', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "rows" ("id" varchar not null, "case_id" varchar not null, "row_index" integer not null, "data" text not null default '{}', "cell_statuses" text not null default '{}', "cell_errors" text not null default '{}', "created_at" datetime, "updated_at" datetime, "import_batch_id" varchar, foreign key("case_id") references "cases"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "contact_rows" ("id" varchar not null, "case_id" varchar not null, "company_row_id" varchar, "row_index" integer not null default '0', "data" text not null default '{}', "cell_statuses" text not null default '{}', "cell_errors" text not null default '{}', "created_at" datetime, "updated_at" datetime, "import_batch_id" varchar, foreign key("case_id") references "cases"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "agent_runs" ("id" varchar not null, "case_id" varchar not null, "goal" text not null, "status" varchar not null default 'planning', "state" text not null, "created_at" datetime, "updated_at" datetime, foreign key("case_id") references "cases"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "scrape_cache" ("url" varchar not null, "markdown" text not null, "title" varchar, "fetched_at" datetime not null, primary key ("url"));
CREATE TABLE IF NOT EXISTS "enrichment_jobs" ("id" varchar not null, "case_id" varchar not null, "column_id" varchar not null, "tool" varchar not null, "status" varchar not null default 'pending', "total_rows" integer not null default '0', "processed_rows" integer not null default '0', "failed_rows" integer not null default '0', "error" text, "config" text, "created_at" datetime, "updated_at" datetime, foreign key("case_id") references "cases"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "user_invitations" ("id" varchar not null, "email" varchar not null, "role" varchar not null default 'Viewer', "token" varchar not null, "invited_by" integer, "expires_at" datetime not null, "accepted_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("invited_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "magic_logins" ("id" varchar not null, "user_id" integer not null, "token" varchar not null, "expires_at" datetime not null, "used_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "user_audits" ("id" varchar not null, "user_id" integer, "action" varchar not null, "ip_address" varchar, "user_agent" text, "details" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "settings" ("id" varchar not null default ('global'), "eden_api_key" text, "eden_region" varchar not null default ('us'), "model_allowlist" text not null default ('[]'), "catalog_domains" text not null default ('[]'), "serper_api_key" text, "serp_api_key" text, "brave_api_key" text, "apify_api_token" text, "firecrawl_api_key" text, "planner_system_prompt" text, "created_at" datetime, "updated_at" datetime, "custom_templates" text default ('[]'), primary key ("id"));
CREATE TABLE IF NOT EXISTS "logs" ("id" integer primary key autoincrement not null, "case_id" varchar not null, "message" text not null, "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "import_batches" ("id" varchar not null, "label" varchar not null, "case_id" varchar, "status" varchar not null default 'pending', "total_rows" integer not null default '0', "normalized_rows" integer not null default '0', "promoted_rows" integer not null default '0', "schema_type" varchar, "created_at" datetime, "updated_at" datetime, foreign key("case_id") references "cases"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "raw_imports" ("id" varchar not null, "import_batch_id" varchar not null, "case_id" varchar, "batch_label" varchar, "source_row_index" integer not null default '0', "raw_data" text not null default '{}', "normalized_data" text, "status" varchar not null default 'pending', "confidence_score" float, "ai_notes" text, "schema_type" varchar, "created_at" datetime, "updated_at" datetime, foreign key("import_batch_id") references "import_batches"("id") on delete cascade, foreign key("case_id") references "cases"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "normalization_prompts" ("id" varchar not null, "name" varchar not null, "description" text, "schema_type" varchar not null default '*', "system_prompt" text not null, "user_prompt_template" text not null, "model" varchar not null default 'openai/gpt-4o', "max_tokens" integer not null default '4000', "temperature" float not null default '0', "max_rows_per_chunk" integer not null default '10', "is_active" tinyint(1) not null default '0', "version" integer not null default '1', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "batch_evaluation_runs" ("id" varchar not null, "import_batch_id" varchar not null, "prompt_id" varchar, "sample_percent" integer not null default '10', "rows_processed" integer not null default '0', "rows_normalized" integer not null default '0', "rows_error" integer not null default '0', "avg_confidence" float, "conf_high_count" integer not null default '0', "conf_mid_count" integer not null default '0', "conf_low_count" integer not null default '0', "hallucination_flags" text not null default '[]', "tokens_used" integer, "cost_usd" float, "duration_ms" integer, "status" varchar not null default 'running', "created_at" datetime, "updated_at" datetime, foreign key("import_batch_id") references "import_batches"("id") on delete cascade, foreign key("prompt_id") references "normalization_prompts"("id") on delete set null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "blacklist_domains" ("id" varchar not null, "domain" varchar not null, "reason" varchar, "added_by" varchar not null default 'system', "hit_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, primary key ("id"));
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "permissions_name_guard_name_unique" on "permissions" ("name", "guard_name");
CREATE UNIQUE INDEX "roles_name_guard_name_unique" on "roles" ("name", "guard_name");
CREATE INDEX "model_has_permissions_model_id_model_type_index" on "model_has_permissions" ("model_id", "model_type");
CREATE INDEX "model_has_roles_model_id_model_type_index" on "model_has_roles" ("model_id", "model_type");
CREATE INDEX "idx_rows_case_id" on "rows" ("case_id", "row_index");
CREATE INDEX "rows_case_id_index" on "rows" ("case_id");
CREATE INDEX "contact_rows_case_id_index" on "contact_rows" ("case_id");
CREATE INDEX "contact_rows_company_row_id_index" on "contact_rows" ("company_row_id");
CREATE INDEX "agent_runs_case_id_index" on "agent_runs" ("case_id");
CREATE INDEX "agent_runs_status_index" on "agent_runs" ("status");
CREATE INDEX "enrichment_jobs_case_id_index" on "enrichment_jobs" ("case_id");
CREATE INDEX "enrichment_jobs_status_index" on "enrichment_jobs" ("status");
CREATE INDEX "user_invitations_email_index" on "user_invitations" ("email");
CREATE UNIQUE INDEX "user_invitations_token_unique" on "user_invitations" ("token");
CREATE UNIQUE INDEX "magic_logins_token_unique" on "magic_logins" ("token");
CREATE INDEX "logs_case_id_index" on "logs" ("case_id");
CREATE INDEX "import_batches_case_id_index" on "import_batches" ("case_id");
CREATE INDEX "raw_imports_import_batch_id_status_index" on "raw_imports" ("import_batch_id", "status");
CREATE INDEX "raw_imports_import_batch_id_index" on "raw_imports" ("import_batch_id");
CREATE INDEX "raw_imports_case_id_index" on "raw_imports" ("case_id");
CREATE INDEX "rows_import_batch_id_index" on "rows" ("import_batch_id");
CREATE INDEX "contact_rows_import_batch_id_index" on "contact_rows" ("import_batch_id");
CREATE INDEX "normalization_prompts_schema_type_is_active_index" on "normalization_prompts" ("schema_type", "is_active");
CREATE INDEX "batch_evaluation_runs_import_batch_id_index" on "batch_evaluation_runs" ("import_batch_id");
CREATE INDEX "batch_evaluation_runs_prompt_id_index" on "batch_evaluation_runs" ("prompt_id");
CREATE UNIQUE INDEX "blacklist_domains_domain_unique" on "blacklist_domains" ("domain");
PRAGMA writable_schema=OFF;
COMMIT;
